import type { ImageLoaderProps } from 'next/image';

/**
 * Maps a source path to the AVIF variant generated by scripts/images.mjs:
 *   /images/duplat/duplat1.webp @1080 -> /img/duplat/duplat1-1080.avif
 * Anything outside /images/ (og image, favicons…) is served as is.
 */
export default function imageLoader({ src, width }: ImageLoaderProps) {
  if (!src.startsWith('/images/')) return src;
  const base = src.slice('/images/'.length).replace(/\.[^.]+$/, '');
  return `/img/${base}-${width}.avif`;
}
